_GENERATED_TRANSLATION_UNIT = "src/typed_generated/typed_slice.cpp"


def _row_without_translation_unit_hash(row):
    """One manifest row with the whole-translation-unit hash removed.

    The emitter writes that hash TWICE per row. `output_sha256` has always
    carried it; since the DSL/Task-7 route work `factory_route.source_sha256`
    carries it again for every route whose `source` IS the generated
    translation unit. That digest is a property of the whole slice, not of the
    program, so it necessarily differs between any two projections and says
    nothing about whether a row was perturbed. The row-isolation proofs have
    always excluded the first copy; this drops the second copy so they keep
    measuring the row.

    The discriminator is the route's own `source` field, not equality of the
    two digests. A route that names a DIFFERENT file keeps its digest and
    stays compared -- `classicNoisedeck/bitEffects:bitEffects` is a
    `custom_adapter` whose `factory_route.source` is
    `src/effects/bit_effects.cpp` and whose digest is a real, stable identity.
    Equality was tried first and is NOT usable here: under
    `historical_cross_lane` the two carriers legitimately disagree, because
    that helper recomputes `output_sha256` after stripping the bitEffects
    include but does not know about the second carrier. See the round-2
    section of task-7-typed-generator-census-repair.md.

    Every other field of `factory_route` -- factory, kind, source -- stays
    compared, so this is strictly narrower than excluding the block.
    """
    trimmed = {name: value for name, value in row.items()
               if name != "output_sha256"}
    route = trimmed.get("factory_route")
    if (isinstance(route, dict)
            and route.get("source") == _GENERATED_TRANSLATION_UNIT):
        trimmed["factory_route"] = {
            name: value for name, value in route.items()
            if name != "source_sha256"}
    return trimmed


class LightLeakPhase2Tests(unittest.TestCase):
    def test_lands_sorted_row_and_exact_out_abi(self) -> None:
        import hashlib

        from tools.glslcpp import check_corpus, generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import (
            TypedEmissionError, render_typed_cpp)
        from tools.glslcpp.frontend import parse_program
        from tools.glslcpp.frontend.out_inout_admission_profile import (
            LIGHTLEAK_KEY, LIGHTLEAK_PROFILE)
        from tools.glslcpp.frontend.semantic import analyze_program

        spec = json.loads(
            (REPOSITORY / "tools/glslcpp/typed_slice.json").read_text())
        keys = [item["program_key"] for item in spec["programs"]]
        self.assertEqual(211, len(keys))
        self.assertEqual(72, keys.index(LIGHTLEAK_KEY))
        row = spec["programs"][keys.index(LIGHTLEAK_KEY)]
        self.assertEqual(
            {"defines": {}, "program_key": LIGHTLEAK_KEY,
             "out_inout_admission_profile": LIGHTLEAK_PROFILE}, row)

        source_path = (check_corpus._corpus_root(REPOSITORY)
                       / "sources/filter/lightLeak/lightLeak.glsl")
        source = source_path.read_text(encoding="utf-8")
        source_hash = hashlib.sha256(source.encode()).hexdigest()
        typed = analyze_program(
            parse_program(source, LIGHTLEAK_KEY, {}), LIGHTLEAK_KEY,
            source_global_literal_int_profile="source-global-literal-int-v1")
        emitted = render_typed_cpp(
            typed, LIGHTLEAK_KEY, source_hash,
            source_global_literal_int_profile="source-global-literal-int-v1",
            out_inout_admission_profile=LIGHTLEAK_PROFILE)
        self.assertIn("glsl::Vec3& cell_color", emitted)
        self.assertIn("float& cell_dist", emitted)
        self.assertEqual(2, emitted.count("voronoiCell(state, context"))

        generated_cpp = (
            REPOSITORY / "src/typed_generated/typed_slice.cpp").read_text()
        marker = f"// Typed IR program: {LIGHTLEAK_KEY}\n"
        self.assertEqual(1, generated_cpp.count(marker))
        self.assertIn(f"{marker}// Source SHA-256: {source_hash}\n", generated_cpp)
        self.assertEqual(
            1, generated_cpp.count(
                "BoundKernel bind_filter_lightLeak_lightLeak("))

        manifest = json.loads((
            REPOSITORY / "src/typed_generated/typed_manifest.json").read_text())
        manifest_rows = [item for item in manifest["programs"]
                         if item["program_key"] == LIGHTLEAK_KEY]
        self.assertEqual(1, len(manifest_rows))
        self.assertEqual(source_hash, manifest_rows[0]["source_sha256"])
        self.assertEqual(LIGHTLEAK_PROFILE,
                         manifest_rows[0]["out_inout_admission_profile"])
        self.assertEqual("bind_filter_lightLeak_lightLeak",
                         manifest_rows[0]["factory"])
        catalog = (
            REPOSITORY / "include/noisemaker/generated/catalog.hpp").read_text()
        self.assertEqual(
            1, catalog.count(
                "BoundKernel bind_filter_lightLeak_lightLeak("))

        with self.assertRaises(TypedEmissionError):
            render_typed_cpp(typed, LIGHTLEAK_KEY, source_hash)
        with self.assertRaises(TypedEmissionError):
            render_typed_cpp(
                typed, LIGHTLEAK_KEY, source_hash,
                out_inout_admission_profile="wrong-lightleak-profile")

    def test_generated_slice_has_a_portable_cpp20_smoke_compile(self) -> None:
        import shutil
        import subprocess
        import tempfile

        compiler = shutil.which("clang++") or shutil.which("g++")
        if compiler is None:
            self.skipTest("no C++20 compiler available")
        with tempfile.TemporaryDirectory(prefix="noisemaker-lightleak-compile-") as temporary:
            subprocess.run(
                [compiler, "-std=c++20", "-Wall", "-Wextra", "-Wpedantic",
                 "-Werror", "-ffp-contract=off", "-I", str(REPOSITORY / "include"),
                 "-c", str(REPOSITORY / "src/typed_generated/typed_slice.cpp"),
                 "-o", str(pathlib.Path(temporary) / "typed_slice.o")],
                check=True, cwd=REPOSITORY)


class ClassicNoiseIntegrationTests(unittest.TestCase):
    KEY = "classicNoisedeck/noise:noise"
    PROFILE = "classic-noise-frontend-admission-v1"
    DEFINES = {
        "COLOR_MODE": 6,
        "LOOP_OFFSET": 300,
        "METRIC": 0,
        "NOISE_TYPE": 10,
        "REFRACT_MODE": 2,
    }

    def test_classic_noise_is_the_exact_live_row_211(self) -> None:
        import hashlib
        from tools.glslcpp import generate_typed_slice

        spec = generate_typed_slice.load_slice(REPOSITORY)
        keys = [item["program_key"] for item in spec["programs"]]
        self.assertEqual(211, len(keys))
        self.assertEqual(13, keys.index(self.KEY))
        self.assertEqual(
            "29a148b26cfe4f550ac82325810655eb0e5ffad2c3a4e5241e42600bac9f76c1",
            hashlib.sha256(("\n".join(keys) + "\n").encode()).hexdigest())
        self.assertEqual(
            {"defines": self.DEFINES,
             "noise_frontend_profile": self.PROFILE,
             "program_key": self.KEY},
            spec["programs"][13])

        manifest = json.loads(
            (REPOSITORY / "src/typed_generated/typed_manifest.json").read_text())
        row = next(item for item in manifest["programs"]
                   if item["program_key"] == self.KEY)
        self.assertEqual(self.DEFINES, row["defines"])
        self.assertEqual(self.PROFILE, row["noise_frontend_profile"])
        self.assertNotIn("runtime_loop_bound_profile", row)
        self.assertEqual("bind_classicNoisedeck_noise_noise", row["factory"])
        self.assertEqual(211, len(manifest["programs"]))

        generated = (REPOSITORY / "src/typed_generated/typed_slice.cpp").read_text()
        self.assertEqual(1, generated.count("// Typed IR program: " + self.KEY))
        start = generated.index("// Typed IR program: " + self.KEY)
        end = generated.index("// Typed IR program:", start + 1)
        self.assertIn("namespace typed_13 {", generated[start:end])
        catalog = (REPOSITORY / "include/noisemaker/generated/catalog.hpp").read_text()
        self.assertEqual(213, catalog.count("[[nodiscard]] BoundKernel bind_"))
        self.assertEqual(1, catalog.count("bind_classicNoisedeck_noise_noise"))


