class Task33DerivativeAdmissionTests(unittest.TestCase):
    """dFdx/dFdy/fwidth, admitted by node identity for 17 programs at once
    via one shared profile (derivative-admission-v1), following the
    round/tanh/floatBitsToUint/all+lessThanEqual precedent. `posterize` and
    `waves` were originally excluded (unrelated `round`/`any` blockers) and
    landed later once posterize-round-admission-v1 /
    waves-any-notequal-admission-v1 admitted their second, unrelated
    builtin gap -- see `_extra_admission_kwargs` below for the one extra
    profile parameter each of those two needs beyond
    derivative_admission_profile alone."""

    KEYS = (
        "filter/bulge:bulge", "filter/celShading:celShadingColor",
        "filter/halftone:halftone", "filter/lens:lens",
        "filter/lensWarp:lensWarp", "filter/octaveWarp:octaveWarp",
        "filter/pinch:pinch", "filter/polar:polar",
        "filter/pondRipples:pondRipples", "filter/posterize:posterize",
        "filter/spiral:spiral", "filter/stamp:stThreshold",
        "filter/step:step", "filter/stipple:stipple", "filter/tunnel:tunnel",
        "filter/warp:warp", "filter/waves:waves",
    )

    @staticmethod
    def _extra_admission_kwargs(key):
        """Posterize/waves each need one more profile parameter beyond
        derivative_admission_profile alone (deliberately not mutually
        exclusive with it -- the Grade LUMA-weights/index-expression
        coexistence precedent). Every other key needs nothing extra."""
        from tools.glslcpp.frontend.posterize_round_profile import (
            POSTERIZE_KEY, PROFILE as POSTERIZE_ROUND_PROFILE)
        from tools.glslcpp.frontend.waves_any_notequal_profile import (
            WAVES_KEY, PROFILE as WAVES_ANY_NOTEQUAL_PROFILE)
        if key == POSTERIZE_KEY:
            return {"posterize_round_profile": POSTERIZE_ROUND_PROFILE}
        if key == WAVES_KEY:
            return {"waves_any_notequal_profile": WAVES_ANY_NOTEQUAL_PROFILE}
        return {}

    @staticmethod
    def exact_program(key):
        import hashlib
        from tools.glslcpp import check_corpus
        from tools.glslcpp.frontend import parse_program
        from tools.glslcpp.frontend.semantic import analyze_program
        from tools.glslcpp.generate_typed_slice import _defaults

        root = check_corpus._corpus_root(REPOSITORY)
        manifest = check_corpus._load_json(root / "manifest.json", "manifest")
        entries = {item["program_key"]: item
                  for item in check_corpus._validate_manifest(manifest)}
        source = (root / entries[key]["source"]).read_text()
        defines = _defaults(REPOSITORY, key)
        return (source, hashlib.sha256(source.encode()).hexdigest(),
                analyze_program(parse_program(source, key, defines), key))

    def test_task33_all_seventeen_authenticate_and_lower_with_narrow_abi(self) -> None:
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import TypedEmissionError, render_typed_cpp
        from tools.glslcpp.frontend.derivative_admission_profile import (
            DERIVATIVE_ADMISSION_KEYS, PROFILE, apply_derivative_admission,
            authenticate_derivative_admission)

        self.assertEqual(frozenset(self.KEYS), DERIVATIVE_ADMISSION_KEYS)
        for key in self.KEYS:
            with self.subTest(key=key):
                _, source_hash, exact = self.exact_program(key)
                proof = authenticate_derivative_admission(exact, source_hash, PROFILE)
                self.assertTrue(exact.resources.uses_derivatives)
                self.assertGreaterEqual(len(proof.nodes), 1)
                self.assertTrue(all(item.callee in ("dFdx", "dFdy", "fwidth")
                                    for item in proof.nodes))
                self.assertIs(exact, apply_derivative_admission(exact, source_hash, PROFILE))
                extra = self._extra_admission_kwargs(key)

                # Without the carrier, both authorities fail closed.
                with self.assertRaises(generate_typed_slice.GeneratorError):
                    generate_typed_slice.validate_capabilities(
                        exact, generate_typed_slice.APPROVED_CAPABILITIES,
                        source_hash=source_hash)
                with self.assertRaises(TypedEmissionError):
                    render_typed_cpp(exact, exact.key, source_hash)

                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash, derivative_admission_profile=PROFILE,
                    **extra)
                emitted = render_typed_cpp(
                    exact, exact.key, source_hash, derivative_admission_profile=PROFILE,
                    **extra)
                for item in proof.nodes:
                    self.assertIn(f"glsl::{item.callee}(context, ", emitted)
                # Narrow-ABI lowering: exactly as many derivative call
                # lowerings as authenticated nodes -- never more.
                total = sum(emitted.count(f"glsl::{name}(context, ")
                           for name in ("dFdx", "dFdy", "fwidth"))
                self.assertEqual(len(proof.nodes), total)

    def test_task33_single_axis_structural_mutations_reject_at_all_three_authorities(self) -> None:
        import copy
        import dataclasses
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import TypedEmissionError, render_typed_cpp
        from tools.glslcpp.frontend.derivative_admission_profile import (
            PROFILE, authenticate_derivative_admission)
        from tools.glslcpp.frontend.semantic_types import vector
        from tools.glslcpp.frontend.typed_ir import PreprocessorDefine

        _, source_hash, exact = self.exact_program("filter/bulge:bulge")

        # Located by walk (kind/callee filter), never by a hardcoded index
        # path -- bulge's `if (antialias)` block is not main's first `if`,
        # so a position-based path is fragile; a walk is not.
        def walk_expression(value):
            yield value
            for child in value.children:
                yield from walk_expression(child)

        def walk_statement(statement):
            yield statement
            for child in statement.children:
                yield from walk_statement(child)

        def sites(program, function_id, callee):
            function = next(item for item in program.functions if item.id == function_id)
            return [node
                    for statement in function.body
                    for owner in walk_statement(statement)
                    for expression in owner.expressions
                    for node in walk_expression(expression)
                    if node.kind == "builtin" and node.callee == callee]

        dfdx_node = sites(exact, 14, "dFdx")
        dfdy_node = sites(exact, 14, "dFdy")
        self.assertEqual(1, len(dfdx_node))
        self.assertEqual(1, len(dfdy_node))
        self.assertEqual((74, 19), (dfdx_node[0].span.start_line, dfdx_node[0].span.start_column))
        self.assertEqual((75, 19), (dfdy_node[0].span.start_line, dfdy_node[0].span.start_column))

        top_level_axes = {
            "program-key": ("key", "filter/bulge:foreign"),
            "normalized-source": ("source", exact.source + " "),
            "raw-source": ("raw_source", exact.raw_source + " "),
            "body-status": ("body_status", "task33-mutated"),
            "define-injected": ("preprocessor_defines",
                                (PreprocessorDefine("TASK33", "int", "1"),)),
            "struct-presence": ("structs", (object(),)),
            "uniform-block-presence": ("uniform_blocks", (object(),)),
            "resource-uniform-order": ("resources", dataclasses.replace(
                exact.resources, uniforms=tuple(reversed(exact.resources.uniforms)))),
            "resource-uniform-count": ("resources", dataclasses.replace(
                exact.resources, uniforms=exact.resources.uniforms[:-1])),
            "resource-texture": ("resources", dataclasses.replace(
                exact.resources, uses_texture=False)),
            "resource-derivative-off": ("resources", dataclasses.replace(
                exact.resources, uses_derivatives=False)),
            "function-count": ("functions", exact.functions[:-1]),
            "function-order": ("functions", tuple(reversed(exact.functions))),
            "loop-proof": ("counted_loop_proof", dataclasses.replace(
                exact.counted_loop_proof, loop_count=2)),
        }
        candidates = {name: dataclasses.replace(exact, **{field: value})
                     for name, (field, value) in top_level_axes.items()}

        # Node-level axes: an independent deep copy per axis (so mutating one
        # candidate's node objects in place never leaks into another), then
        # bypass-mutated via object.__setattr__ (the frozen-dataclass escape
        # hatch this codebase's own profiles use for the same purpose).
        def node_candidate(callee, field, value):
            candidate = copy.deepcopy(exact)
            node = sites(candidate, 14, callee)[0]
            object.__setattr__(node, field, value)
            return candidate

        candidates["dfdx-span"] = node_candidate(
            "dFdx", "span", dataclasses.replace(dfdx_node[0].span, start_column=99))
        candidates["dfdx-callee"] = node_candidate("dFdx", "callee", "abs")
        candidates["dfdx-type"] = node_candidate("dFdx", "type", vector("float", 3))
        candidates["dfdx-children-count"] = node_candidate("dFdx", "children", ())
        candidates["dfdy-span"] = node_candidate(
            "dFdy", "span", dataclasses.replace(dfdy_node[0].span, start_column=99))
        candidates["dfdy-callee"] = node_candidate("dFdy", "callee", "abs")
        candidates["dfdy-type"] = node_candidate("dFdy", "type", vector("float", 3))
        candidates["dfdy-children-count"] = node_candidate("dFdy", "children", ())

        self.assertEqual(22, len(candidates))

        for name, candidate in candidates.items():
            self.assertNotEqual(exact, candidate, name)
            with self.subTest(axis=name, layer="profile"), self.assertRaises(ValueError):
                authenticate_derivative_admission(candidate, source_hash, PROFILE)
            with self.subTest(axis=name, layer="validator"), self.assertRaises(
                    generate_typed_slice.GeneratorError):
                generate_typed_slice.validate_capabilities(
                    candidate, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash, derivative_admission_profile=PROFILE)
            with self.subTest(axis=name, layer="emitter"), self.assertRaises(
                    TypedEmissionError):
                render_typed_cpp(
                    candidate, candidate.key, source_hash,
                    derivative_admission_profile=PROFILE)

    def test_task33_node_level_closure_logic_rejects_past_the_coarse_hash_gate(self) -> None:
        """Prove the profile's node-walk/typing logic itself rejects, not
        just the coarse whole-program hash gate (a prior task shipped a
        near-vacuous test this way -- 46 of 47 axes absorbed by that gate).

        The coarse hashes are deliberately re-frozen to match each mutated
        tree here, so the node-level checks actually execute. Each mutation
        must then be rejected by a SPECIFIC node-level message, never the
        generic coarse one.

        Non-vacuity proven by sabotage (transcript in the task report):
        the `if actual_nodes != nodes: raise ...` line in
        derivative_admission_profile.py was disabled (short-circuited to
        `if False and ...`) and this test rerun. 3 of the 5 cases below
        (orphan-child, widened-arity, retyped-argument) immediately failed
        -- proving this test genuinely exercises that line, not just the
        coarse gate. The other 2 (renamed-away-from-census,
        colliding-function-id) kept passing under that same sabotage,
        because they are independently caught by a different, earlier
        check (cardinality / function-inventory) -- real defense in depth,
        not a second vacuous path. The file was restored byte-identical
        (diffed against a pre-sabotage copy) and this test reconfirmed
        green before landing.
        """
        import hashlib
        from tools.glslcpp.frontend import derivative_admission_profile as profile

        COARSE = ("source, define, function, whole-program, "
                  "or interface mismatch")

        def walk_expression(value):
            yield value
            for child in value.children:
                yield from walk_expression(child)

        def walk_statement(statement):
            yield statement
            for child in statement.children:
                yield from walk_statement(child)

        def function_by_id(program, function_id):
            return next(item for item in program.functions if item.id == function_id)

        def sites(program, function_id, callee):
            function = function_by_id(program, function_id)
            return [node
                    for statement in function.body
                    for owner in walk_statement(statement)
                    for expression in owner.expressions
                    for node in walk_expression(expression)
                    if node.kind == "builtin" and node.callee == callee]

        def rename_dfdx(program):
            # Renamed OUT of the derivative-builtin census filter entirely
            # (not to another derivative name), so the site count itself
            # drops -- the cardinality-mismatch axis, mirroring Task 31's
            # "tanh renamed to sin" (sin is likewise outside that census).
            object.__setattr__(sites(program, 14, "dFdx")[0], "callee", "abs")

        def orphan_dfdy_child(program):
            object.__setattr__(sites(program, 14, "dFdy")[0], "children", ())

        def widen_dfdx_arity(program):
            node = sites(program, 14, "dFdx")[0]
            object.__setattr__(node, "children", (*node.children, node.children[0]))

        def retype_dfdy_argument(program):
            from tools.glslcpp.frontend.semantic_types import vector
            node = sites(program, 14, "dFdy")[0]
            object.__setattr__(node.children[0], "type", vector("float", 3))

        def collide_rotate2d_function_id(program):
            function = function_by_id(program, 15)
            object.__setattr__(function.signature, "id", 14)

        cases = (
            ("dFdx renamed to dFdy at the one authorized site",
             rename_dfdx, "closure site cardinality mismatch"),
            ("dFdy loses its only child",
             orphan_dfdy_child, "closure node identity mismatch"),
            ("dFdx gains a second argument",
             widen_dfdx_arity, "closure node identity mismatch"),
            ("dFdy's vec2 argument retyped to vec3",
             retype_dfdy_argument, "closure node identity mismatch"),
            ("rotate2D's function id perturbed to collide with main",
             collide_rotate2d_function_id, "function inventory mismatch"),
        )

        _, source_hash, baseline = self.exact_program("filter/bulge:bulge")
        baseline_functions = profile._sha(baseline.functions)

        for label, mutate, expected in cases:
            with self.subTest(node_axis=label):
                _, _, candidate = self.exact_program("filter/bulge:bulge")
                mutate(candidate)
                self.assertNotEqual(baseline_functions,
                                    profile._sha(candidate.functions), label)

                normalized = candidate.source.encode("utf-8")
                loop_proof = candidate.counted_loop_proof
                patched_functions = tuple(
                    (row[0], row[1], row[2], row[3], row[4], row[5],
                     profile._sha(candidate.functions), profile._whole(candidate),
                     profile._interface(candidate), row[9], row[10], row[11],
                     row[12], row[13])
                    if row[0] == candidate.key else row
                    for row in profile._profile_tuple())
                new_repr = repr(patched_functions)
                with mock.patch.multiple(
                        profile,
                        _FROZEN_PROFILE_TUPLE_REPR=new_repr,
                        _PROFILE_SHA256=profile._sha(patched_functions)):
                    with self.assertRaises(ValueError) as raised:
                        profile.authenticate_derivative_admission(
                            candidate, source_hash, profile.PROFILE)
                message = str(raised.exception)
                self.assertNotIn(COARSE, message,
                                 f"{label} was absorbed by the coarse gate")
                self.assertIn(expected, message, label)

        # Restore: the patched constants only lived inside the `with`
        # blocks above, but re-authenticate the real program to be certain
        # later tests inherit a working profile.
        _, source_hash, exact = self.exact_program("filter/bulge:bulge")
        profile.authenticate_derivative_admission(exact, source_hash, profile.PROFILE)

    def test_task33_validator_and_emitter_authenticate_independently_without_trusting_each_other(self) -> None:
        import dataclasses
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import TypedEmissionError, render_typed_cpp
        from tools.glslcpp.frontend.derivative_admission_profile import PROFILE

        _, source_hash, exact = self.exact_program("filter/bulge:bulge")
        foreign = dataclasses.replace(exact, key="filter/bulge:foreignvariant")

        with self.assertRaisesRegex(TypedEmissionError, r"exact .* carrier required"):
            render_typed_cpp(exact, exact.key, source_hash)
        with self.assertRaises(TypedEmissionError):
            render_typed_cpp(exact, exact.key, source_hash,
                             derivative_admission_profile="wrong")
        with self.assertRaises(TypedEmissionError):
            render_typed_cpp(foreign, foreign.key, source_hash,
                             derivative_admission_profile=PROFILE)
        with self.assertRaises(TypedEmissionError):
            render_typed_cpp(foreign, foreign.key, source_hash)

        with self.assertRaisesRegex(
                generate_typed_slice.GeneratorError, r"exact .* carrier required"):
            generate_typed_slice.validate_capabilities(
                exact, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash)
        with self.assertRaises(generate_typed_slice.GeneratorError):
            generate_typed_slice.validate_capabilities(
                exact, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash, derivative_admission_profile="wrong")
        with self.assertRaises(generate_typed_slice.GeneratorError):
            generate_typed_slice.validate_capabilities(
                foreign, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash, derivative_admission_profile=PROFILE)

        # Mocking one authority's authenticate function to hand back a
        # PROOF BUILT FROM A DIFFERENT TREE must not let the other authority
        # (which independently re-derives node identity from the actual
        # candidate) through.
        _, _, proof_source = self.exact_program("filter/bulge:bulge")
        from tools.glslcpp.frontend.derivative_admission_profile import (
            authenticate_derivative_admission)
        real_proof = authenticate_derivative_admission(proof_source, source_hash, PROFILE)
        with mock.patch.object(
                generate_typed_slice, "authenticate_derivative_admission",
                return_value=real_proof), self.assertRaises(
                    generate_typed_slice.GeneratorError):
            generate_typed_slice.validate_capabilities(
                foreign, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash, derivative_admission_profile=PROFILE)
        with mock.patch(
                "tools.glslcpp.emit_typed_cpp.authenticate_derivative_admission",
                return_value=real_proof), self.assertRaises(TypedEmissionError):
            render_typed_cpp(foreign, foreign.key, source_hash,
                             derivative_admission_profile=PROFILE)

    def test_task33_capability_vocabulary_is_identity_scoped_not_widened(self) -> None:
        from tools.glslcpp import emit_typed_cpp, generate_typed_slice

        for name in ("dFdx", "dFdy", "fwidth"):
            self.assertNotIn(name, generate_typed_slice.APPROVED_CAPABILITIES)
            self.assertNotIn(name, generate_typed_slice._BUILTINS)
            self.assertNotIn(name, emit_typed_cpp._BUILTIN_NAMES)
        self.assertEqual(44, len(generate_typed_slice.APPROVED_CAPABILITIES))
        spec = generate_typed_slice.load_slice(REPOSITORY)
        self.assertEqual(44, len(spec["capabilities"]))

        # Behavioral proof: validate_capabilities succeeds against the
        # UNMODIFIED 44-entry tuple for every one of the 17 admitted
        # programs -- direct evidence none of dFdx/dFdy/fwidth ever enters
        # `used`.
        from tools.glslcpp.frontend.derivative_admission_profile import PROFILE
        for key in self.KEYS:
            with self.subTest(key=key):
                _, source_hash, exact = self.exact_program(key)
                extra = self._extra_admission_kwargs(key)
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash, derivative_admission_profile=PROFILE,
                    **extra)
                emit_typed_cpp.render_typed_cpp(
                    exact, exact.key, source_hash,
                    derivative_admission_profile=PROFILE, **extra)

        # Identity scoping proven behaviorally: a foreign (differently-keyed)
        # program carrying the identical closure is rejected at both
        # authorities.
        import dataclasses
        _, source_hash, exact = self.exact_program("filter/bulge:bulge")
        foreign = dataclasses.replace(exact, key="filter/bulge:foreignvariant")
        with self.assertRaisesRegex(
                generate_typed_slice.GeneratorError,
                r"unsupported builtin (dFdx|dFdy)"):
            generate_typed_slice.validate_capabilities(
                foreign, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash)
        from tools.glslcpp.emit_typed_cpp import TypedEmissionError
        with self.assertRaisesRegex(
                TypedEmissionError, r"unsupported builtin (dFdx|dFdy)"):
            emit_typed_cpp.render_typed_cpp(foreign, foreign.key, source_hash)

    def test_task33_history_schema_and_vendored_oracle_match_152_program_state(self) -> None:
        import hashlib
