    # ---- the gates and their ledgers -------------------------------------

    def test_every_gate_ledger_is_load_bearing(self) -> None:
        """Each of the validator's three declaration gates and its read
        traversal, and the emitter's admission, alias, local, constructor and
        read ledgers, caught by ITS OWN message.

        Driven by stubbing the closure accessors so a gate can be starved
        without touching the frozen record: an authority that silently stops
        consuming an authenticated node is exactly what these exist to name.
        """
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import (
            TypedEmissionError, render_typed_cpp)
        from tools.glslcpp.frontend import const_global_table_profile

        source_hash, exact = self.exact_program()
        declarations = const_global_table_profile.\
            authenticate_const_global_tables(exact, source_hash, self.PROFILE)
        reads = const_global_table_profile.\
            authenticate_const_global_table_reads(exact, source_hash,
                                                  self.PROFILE)
        self.assertEqual(3, len(declarations))
        self.assertEqual(3, len(reads))
        # Nine distinct live node objects across the three read records, all
        # of them out of `exact` rather than copies.
        self.assertEqual(9, len({id(node) for item in reads
                                 for node in (item.node, item.base,
                                              item.index)}))

        # A declaration the gates never see: every declaration ledger starves.
        short = declarations[:2]
        with mock.patch.object(generate_typed_slice,
                               "authenticate_const_global_tables",
                               lambda *a, **k: short):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    re.escape("const-global nine-table carrier cardinality "
                              "mismatch")):
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    as_u32_round_profile=self.ROUND,
                    const_global_table_profile=self.PROFILE)

        # A read node the index arm can never reach: the traversal ledger
        # fires with its own message, not the declaration ledgers'.
        import dataclasses
        detached = reads[:2] + (reads[2]._replace(
            node=dataclasses.replace(reads[2].node)),)
        with mock.patch.object(generate_typed_slice,
                               "authenticate_const_global_table_reads",
                               lambda *a, **k: detached):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    re.escape("unsupported typed expression index")):
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    as_u32_round_profile=self.ROUND,
                    const_global_table_profile=self.PROFILE)
        # Reordered records: every node is still authenticated and still
        # reached, so only the FROZEN ORDER clause can fire.
        reordered = (reads[1], reads[0], reads[2])
        with mock.patch.object(generate_typed_slice,
                               "authenticate_const_global_table_reads",
                               lambda *a, **k: reordered):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    re.escape("authenticated const-global nine-table read "
                              "traversal mismatch")):
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    as_u32_round_profile=self.ROUND,
                    const_global_table_profile=self.PROFILE)

        # The emitter's own ledgers, independently.
        from tools.glslcpp import emit_typed_cpp
        with mock.patch.object(generate_typed_slice, "validate_capabilities",
                               lambda *a, **k: None):
            with mock.patch.object(emit_typed_cpp,
                                   "authenticate_const_global_tables",
                                   lambda *a, **k: short):
                with self.assertRaisesRegex(
                        TypedEmissionError,
                        re.escape("const-global nine-table carrier "
                                  "cardinality mismatch")):
                    render_typed_cpp(
                        exact, exact.key, source_hash, "typed_probe",
                        "bind_probe", as_u32_round_profile=self.ROUND,
                        const_global_table_profile=self.PROFILE)
            with mock.patch.object(
                    emit_typed_cpp,
                    "authenticate_const_global_table_reads",
                    lambda *a, **k: reordered):
                with self.assertRaisesRegex(
                        TypedEmissionError,
                        re.escape("authenticated const-global nine-table "
                                  "emission mismatch")):
                    render_typed_cpp(
                        exact, exact.key, source_hash, "typed_probe",
                        "bind_probe", as_u32_round_profile=self.ROUND,
                        const_global_table_profile=self.PROFILE)

    def test_admitted_globals_carry_the_const_write_barrier(self) -> None:
        """The inverse of the mutable-global frame's decision.

        `synth/shape`'s two admitted declarations must stay OUT of
        `admitted_globals`, because its own authenticated writes would be
        rejected. These three are genuinely `const`, so they are registered IN
        it and `audit_expression` refuses any write that targets them. The
        frozen source hash means no real tree can reach that barrier, so it is
        exercised here with the closure stubbed onto a tree that carries a
        planted write -- delete the registration and this goes green.
        """
        import dataclasses
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.frontend import const_global_table_profile

        source_hash, exact = self.exact_program()
        declarations = const_global_table_profile.\
            authenticate_const_global_tables(exact, source_hash, self.PROFILE)
        reads = const_global_table_profile.\
            authenticate_const_global_table_reads(exact, source_hash,
                                                  self.PROFILE)
        target = reads[1].node

        def round_nodes(program):
            found = []

            def expression(value):
                if getattr(value, "callee", None) == "round":
                    found.append(value)
                for child in value.children:
                    expression(child)

            def statement(value):
                for item in value.expressions:
                    expression(item)
                for child in value.children:
                    statement(child)

            for function in program.functions:
                for item in function.body:
                    statement(item)
            return tuple(found)

        def expression(value):
            if value is target:
                return dataclasses.replace(
                    value, kind="post", operator="++", children=(value,))
            return dataclasses.replace(
                value, children=tuple(expression(child)
                                      for child in value.children))

        def statement(value):
            return dataclasses.replace(
                value,
                expressions=tuple(expression(item)
                                  for item in value.expressions),
                children=tuple(statement(item) for item in value.children))

        planted = dataclasses.replace(exact, functions=tuple(
            dataclasses.replace(function, body=tuple(
                statement(item) for item in function.body))
            for function in exact.functions))
        planted_rounds = round_nodes(planted)
        self.assertEqual(1, len(planted_rounds))
        # Every carrier this tree needs is stubbed onto the PLANTED tree, so
        # nothing rejects it before the write audit runs -- the frozen source
        # hash would otherwise refuse the mutation first, which is precisely
        # why this barrier is unreachable without stubs.
        with mock.patch.object(generate_typed_slice,
                               "authenticate_const_global_tables",
                               lambda *a, **k: declarations), \
                mock.patch.object(generate_typed_slice,
                                  "authenticate_const_global_table_reads",
                                  lambda *a, **k: reads), \
                mock.patch.object(generate_typed_slice,
                                  "authenticate_as_u32_round_admission",
                                  lambda *a, **k: planted_rounds):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    re.escape("write to source const global")):
                generate_typed_slice.validate_capabilities(
                    planted, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    as_u32_round_profile=self.ROUND,
                    const_global_table_profile=self.PROFILE)

