    def test_carrier_on_a_foreign_key_is_refused_by_both_authorities(self) -> None:
        from tools.glslcpp import generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import (TypedEmissionError,
                                                  render_typed_cpp)
        from tools.glslcpp.frontend.mutable_global_array_profile import (
            allowed_row_fields, authenticate_mutable_global_array,
            frame_contract)

        source_hash, foreign = self.exact_program("synth/solid:solid")
        with self.assertRaisesRegex(
                generate_typed_slice.GeneratorError,
                "mutable-global array profile metadata mismatch"):
            generate_typed_slice.validate_capabilities(
                foreign, generate_typed_slice.APPROVED_CAPABILITIES,
                source_hash=source_hash,
                mutable_global_array_profile=self.PROFILE)
        with self.assertRaisesRegex(
                TypedEmissionError,
                "mutable-global array profile metadata mismatch"):
            render_typed_cpp(foreign, foreign.key, source_hash,
                             mutable_global_array_profile=self.PROFILE)
        # A non-carrier key gets an empty tuple, never an admission; supplying
        # a profile for one is the module's own hard failure.
