    def test_all_five_declarations_are_consumed_exactly_once_by_identity(self) -> None:
        from tools.glslcpp.frontend.mutable_global_array_profile import (
            authenticate_mutable_global_array)

        source_hash, exact = self.exact_program()
        admitted = authenticate_mutable_global_array(exact, source_hash,
                                                     self.PROFILE)
        self.assertEqual(list(self.FIELDS),
                         [item.symbol.name for item in admitted])
        self.assertEqual([17, 18, 19, 20, 21],
                         [item.symbol.id for item in admitted])
        self.assertEqual(5, len({id(item) for item in admitted}))
        for declaration in admitted:
            self.assertTrue(any(declaration is item
                                for item in exact.declarations))
            self.assertIsNone(declaration.initializer)
            self.assertEqual("global", declaration.symbol.storage)
            self.assertEqual("float[9]", declaration.type.display())

    def test_visitation_ledgers_are_load_bearing_at_both_authorities(self) -> None:
        import copy
        from tools.glslcpp import emit_typed_cpp, generate_typed_slice
        from tools.glslcpp.emit_typed_cpp import (TypedEmissionError,
                                                  render_typed_cpp)
        from tools.glslcpp.frontend.mutable_global_array_profile import (
            authenticate_mutable_global_array)

        source_hash, exact = self.exact_program()
        real = authenticate_mutable_global_array(exact, source_hash,
                                                 self.PROFILE)

        # (a) An impostor quintet: same values, different objects. Identity
        #     admission must not recognise it at either authority's gates.
        impostor = tuple(copy.deepcopy(item) for item in real)
        self.assertEqual([item.symbol.id for item in real],
                         [item.symbol.id for item in impostor])
        with mock.patch.object(generate_typed_slice,
                               "authenticate_mutable_global_array",
                               return_value=impostor):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    r"32:1: unsupported global declaration"):
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    mutable_global_array_profile=self.PROFILE)
        with mock.patch.object(emit_typed_cpp,
                               "authenticate_mutable_global_array",
                               return_value=impostor):
            with self.assertRaisesRegex(
                    TypedEmissionError,
                    "unsupported source global declaration"):
                render_typed_cpp(exact, exact.key, source_hash,
                                 mutable_global_array_profile=self.PROFILE)

        # (b) Only the FIRST declaration admitted. The validator names only
        #     `32:1`; an implementation that stopped at one would look correct
        #     until `33:1` reached the second gate. Both authorities refuse
        #     the short tuple on cardinality first.
        with mock.patch.object(generate_typed_slice,
                               "authenticate_mutable_global_array",
                               return_value=real[:1]):
            with self.assertRaisesRegex(
                    generate_typed_slice.GeneratorError,
                    "mutable-global array carrier cardinality mismatch"):
                generate_typed_slice.validate_capabilities(
                    exact, generate_typed_slice.APPROVED_CAPABILITIES,
                    source_hash=source_hash,
                    mutable_global_array_profile=self.PROFILE)
        with mock.patch.object(emit_typed_cpp,
                               "authenticate_mutable_global_array",
                               return_value=real[:1]):
            with self.assertRaisesRegex(
                    TypedEmissionError,
                    "mutable-global array carrier cardinality mismatch"):
                render_typed_cpp(exact, exact.key, source_hash,
                                 mutable_global_array_profile=self.PROFILE)

        # (c) The quintet out of ordinal order: field contracts are
        #     positional, so the emitter must refuse rather than silently
        #     re-order the Frame members.
        with mock.patch.object(emit_typed_cpp,
                               "authenticate_mutable_global_array",
                               return_value=tuple(reversed(real))):
            with self.assertRaisesRegex(
                    TypedEmissionError,
                    "mutable-global array field contract mismatch"):
                render_typed_cpp(exact, exact.key, source_hash,
                                 mutable_global_array_profile=self.PROFILE)

    def test_admitted_arrays_stay_out_of_the_const_write_audit(self) -> None:
        from tools.glslcpp import generate_typed_slice
